<section x-show="tab==='kalender'" class="space-y-5">
    <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-lg font-bold text-slate-900">Kalender shift</h2><p class="mt-1 text-sm text-slate-500">Pilih tanggal untuk mengatur sesi tiap nama. Perubahan hanya berlaku pada tanggal itu.</p></div><div class="flex items-center gap-2"><button type="button" @click="moveMonth(-1)" :disabled="calendarLoading||saving" aria-label="Bulan sebelumnya" class="h-11 w-11 rounded-lg border border-slate-200 bg-white text-slate-600">←</button><label><span class="sr-only">Bulan kalender</span><input type="month" :value="month" @change="changeMonth($event.target.value)" :disabled="calendarLoading||saving" class="h-11 min-w-0 rounded-lg border border-slate-200 bg-white px-3 text-sm"></label><button type="button" @click="moveMonth(1)" :disabled="calendarLoading||saving" aria-label="Bulan berikutnya" class="h-11 w-11 rounded-lg border border-slate-200 bg-white text-slate-600">→</button><button type="button" @click="goToday()" class="hidden h-11 rounded-lg border border-slate-200 bg-white px-3 text-sm sm:block">Hari ini</button></div></div>
    <p x-show="calendarLoading" role="status" class="text-sm text-slate-500">Memuat kalender…</p>
    <div class="overflow-hidden rounded-2xl border border-slate-200 bg-white" :class="calendarLoading?'pointer-events-none opacity-50':''">
        <div class="grid grid-cols-7 bg-slate-50"><template x-for="day in ['Sen','Sel','Rab','Kam','Jum','Sab','Min']" :key="day"><div class="py-3 text-center text-xs font-semibold text-slate-500" x-text="day"></div></template></div>
        <div class="grid grid-cols-7"><template x-for="cell in calendarCells" :key="cell.key"><div class="min-w-0 border-t border-r border-slate-100"><button type="button" x-show="cell.date" @click="openDate(cell.date)" :disabled="saving||calendarLoading" :aria-label="cell.date+', '+cell.count+' anggota'+(cell.custom?', jadwal khusus':'')" :aria-pressed="selectedDate===cell.date" :class="selectedDate===cell.date?'bg-brand-50 ring-2 ring-inset ring-brand-500':'hover:bg-slate-50'" class="min-h-[104px] w-full p-1.5 text-left align-top transition sm:min-h-[142px] sm:p-3"><span class="flex items-center justify-between gap-1"><span :class="cell.date===today?'bg-brand-600 text-white':'text-slate-800'" class="inline-flex h-7 w-7 items-center justify-center rounded-full text-sm font-bold" x-text="cell.day"></span><span x-show="cell.custom" class="h-2 w-2 shrink-0 rounded-full bg-indigo-500" title="Jadwal khusus"></span></span><span class="mt-2 block text-[10px] text-slate-500 sm:text-xs" x-text="cell.count?cell.count+' orang':'Libur'"></span><span class="mt-1 hidden text-xs font-medium text-brand-700 sm:block" x-text="cell.count?number(cell.hours)+' jam video':''"></span><span x-show="cell.custom" class="mt-2 block text-[9px] font-semibold text-indigo-600 sm:text-[10px]">Khusus</span></button><span x-show="!cell.date" class="block min-h-[104px] bg-slate-50/50 sm:min-h-[142px]"></span></div></template></div>
    </div>
    <div class="flex flex-wrap gap-4 text-xs text-slate-500"><span class="flex items-center gap-2"><span class="h-2 w-2 rounded-full bg-indigo-500"></span>Jadwal khusus tanggal</span><span>Tanpa tanda: mengikuti pola rutin dan hari libur.</span></div>
    <section x-show="dayDraft&&calendarReady" class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
        <div class="space-y-4 border-b border-slate-100 p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-brand-700" x-text="dayRevision?'JADWAL KHUSUS':'MENGIKUTI POLA RUTIN'"></p><h2 class="mt-2 text-xl font-bold text-slate-900" x-text="selectedLabel"></h2><p class="mt-1 text-sm text-slate-500">Matikan seluruh sesi pada satu nama untuk meliburkan orang tersebut.</p></div><div class="flex flex-wrap gap-2"><button type="button" @click="markDayOff()" :disabled="saving" class="min-h-[44px] rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600">Liburkan semua</button><button type="button" @click="resetDate()" :disabled="saving" class="min-h-[44px] rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600">Kembali ke pola rutin</button></div></div>
            <div class="flex flex-wrap items-end gap-4" x-show="dayDraft"><label class="text-xs font-semibold text-slate-600">Mulai operasional tanggal ini<input type="time" :value="dayDraft?.start_time || '08:00'" @input="if(dayDraft)dayDraft.start_time=$event.target.value" class="mt-2 block h-11 rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><label class="min-w-[180px] flex-1 text-xs font-semibold text-slate-600">Cari nama<input type="search" x-model="daySearch" placeholder="Cari anggota…" class="mt-2 block h-11 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label></div>
        </div>
        <div class="divide-y divide-slate-100"><template x-for="row in dayWorkers" :key="row.index"><article class="p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="text-sm font-bold text-slate-900" x-text="row.person.name"></h3><p class="mt-1 text-xs text-slate-500" x-text="row.person.sessions.length?number(workHours(row.person,dayDraft))+' jam kerja':'Libur / tidak dijadwalkan'"></p></div><label><span class="sr-only" x-text="'Alat '+row.person.name"></span><select x-model="row.person.alat" class="h-11 rounded-lg border border-slate-200 bg-white px-3 text-sm"><template x-for="tool in dayTools" :key="tool"><option :value="tool" x-text="tool"></option></template></select></label></div><div class="mt-4 flex flex-wrap gap-2"><template x-for="session in daySessions" :key="session.id"><button type="button" @click="toggleSession(row.person,session.id)" :aria-pressed="row.person.sessions.includes(session.id)" :aria-label="row.person.name+', tanggal '+selectedDate+', sesi '+session.id" :class="row.person.sessions.includes(session.id)?'border-brand-600 bg-brand-50 text-brand-700':'border-slate-200 text-slate-500'" class="min-h-[52px] rounded-lg border px-3 py-2 text-left"><span class="block text-xs font-bold" x-text="'Sesi '+session.id"></span><span class="mt-1 block text-[11px]" x-text="session.start+'–'+session.end"></span></button></template><button type="button" @click="row.person.sessions=[]" class="min-h-[52px] rounded-lg border border-dashed border-slate-200 px-3 text-xs text-slate-500">Libur</button></div></article></template></div>
        <div class="space-y-4 border-t border-slate-100 bg-slate-50 p-5 sm:p-6"><label class="block text-xs font-semibold text-slate-600">Tambah anggota khusus tanggal ini<div class="mt-2 flex flex-col gap-2 sm:flex-row"><select x-model="dayAddName" class="h-11 min-w-0 flex-1 rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal"><option value="">Pilih kontributor</option><template x-for="person in dayAvailablePeople" :key="person.id"><option :value="person.nama" x-text="person.nama"></option></template></select><button type="button" @click="addDayWorker()" :disabled="!dayAddName" class="h-11 rounded-lg border border-brand-200 bg-white px-4 text-sm text-brand-700 disabled:opacity-40">Tambah anggota</button></div></label><div class="flex flex-wrap items-center justify-between gap-3"><p class="text-xs text-slate-500" x-text="dayDirty?'Tanggal ini memiliki perubahan belum disimpan.':'Tanggal ini sesuai versi tersimpan.'"></p><button type="button" @click="saveDay()" :disabled="saving||!dayDirty||dayConflicts.length>0||!calendarReady" class="min-h-[44px] rounded-lg bg-brand-600 px-4 text-sm font-semibold text-white disabled:opacity-40" x-text="saving?'Menyimpan…':'Simpan tanggal ini'"></button></div></div>
    </section>
</section>
